def transform(grid):
    g = np.array(grid)
    bg = background(g)
    N = g.shape[0]
    k = 1
    while k * k + k - 1 < N:
        k += 1
    step = k + 1
    objs = objects(g, bg=bg)
    band = max(objs, key=lambda o: o["size"])["colour"]

    # read the motif from a clean slot
    motif = None
    for r in range(k):
        for c in range(k):
            t = g[r*step:r*step+k, c*step:c*step+k]
            if (t == band).any() or (t == bg).all():
                continue
            motif = t.copy()
            break
        if motif is not None:
            break
    mask = motif != bg

    out = g.copy()
    out[out == band] = bg
    emit(out, "Remove the covering band, leaving background.")

    for r in range(k):
        for c in range(k):
            if mask[r, c]:
                out[r*step:r*step+k, c*step:c*step+k] = motif
    emit(out, "Stamp the motif into every lattice slot (r,c) where the motif itself has a cell at (r,c), restoring tiles hidden by the band.")

    for r in range(k):
        for c in range(k):
            if mask[r, c]:
                out[r*step + r, c*step + c] = 8
    emit(out, "In each tile at slot (r,c), mark the motif cell at local position (r,c) with 8.")
    return out
